import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Enterprise SSO: SAML + SCIM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/enterprise-sso.md","filePath":"guide/enterprise-sso.md"}'),n={name:"guide/enterprise-sso.md"};function r(i,e,d,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="enterprise-sso-saml-scim" tabindex="-1">Enterprise SSO: SAML + SCIM <a class="header-anchor" href="#enterprise-sso-saml-scim" aria-label="Permalink to &quot;Enterprise SSO: SAML + SCIM&quot;">​</a></h1><p>Everything on this page ships in the open-source core — there is no paid tier and no SSO tax. Google sign-in (OIDC) stays available alongside; use whichever fits your install.</p><h2 id="saml-sign-in" tabindex="-1">SAML sign-in <a class="header-anchor" href="#saml-sign-in" aria-label="Permalink to &quot;SAML sign-in&quot;">​</a></h2><p>AsyncUp is a standard SAML 2.0 service provider. Any IdP works — Google Workspace, Okta, Microsoft Entra, OneLogin.</p><p><strong>In AsyncUp</strong> (Settings › <em>Sign-in &amp; SSO</em>): paste your IdP&#39;s entity ID, SSO URL, and X.509 certificate.</p><p><strong>In your IdP</strong>: create a custom SAML app with</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>ACS URL</td><td><code>https://&lt;your-host&gt;/auth/saml/acs</code></td></tr><tr><td>SP entity ID / audience</td><td><code>https://&lt;your-host&gt;/auth/saml/metadata</code></td></tr><tr><td>NameID</td><td>the user&#39;s email</td></tr></tbody></table><p>SP metadata XML is served at <code>/auth/saml/metadata</code> for IdPs that import it. The sign-in pages then show a <em>Sign in with SSO (SAML)</em> button.</p><h3 id="who-becomes-an-admin" tabindex="-1">Who becomes an admin <a class="header-anchor" href="#who-becomes-an-admin" aria-label="Permalink to &quot;Who becomes an admin&quot;">​</a></h3><p>Two paths, OR&#39;d — whichever your install has configured grants the admin console:</p><ol><li><strong>IdP group</strong> — an assertion attribute (default name <code>groups</code>) containing the admin value (default <code>asyncup-admins</code>). Both configurable in Settings.</li><li><strong>Google Directory</strong> — when the <a href="./google-chat-setup.html#calendar-ooo">Directory integration</a> is configured, Workspace admins (super or delegated) are admins automatically, same as with Google sign-in.</li></ol><p>Membership note: Google sign-in rejects accounts the Directory doesn&#39;t know; SAML deliberately doesn&#39;t — the IdP itself asserted org membership, and the account may live outside Google (e.g. Okta-only contractors). Suspended accounts are rejected on both paths.</p><p>Everyone else lands on their personal <a href="./web-app.html">page</a> at <code>/app/me</code>.</p><h3 id="how-saml-users-map-to-chat" tabindex="-1">How SAML users map to Chat <a class="header-anchor" href="#how-saml-users-map-to-chat" aria-label="Permalink to &quot;How SAML users map to Chat&quot;">​</a></h3><p>Standup rosters are keyed by Google Chat user ids. A SAML assertion carries an email, which AsyncUp links to the Chat id via the Directory integration (instant) or the cached email from the person&#39;s first bot interaction. Until one of those happens, <code>/app/me</code> shows a &quot;not linked yet&quot; note.</p><h2 id="scim-provisioning" tabindex="-1">SCIM provisioning <a class="header-anchor" href="#scim-provisioning" aria-label="Permalink to &quot;SCIM provisioning&quot;">​</a></h2><p>AsyncUp serves a SCIM 2.0 Users endpoint at <code>/scim/v2</code> for IdPs that push provisioning — Okta, Entra, OneLogin.</p><blockquote><p><strong>Google Workspace cannot push SCIM to custom apps</strong> — its auto-provisioning only covers pre-integrated catalog apps. Pure Google Workspace installs should use the Directory integration instead; SCIM is for orgs whose IdP fronts Google.</p></blockquote><p>Setup: generate the <strong>SCIM provisioning token</strong> (Settings → Access tokens), then configure your IdP with base URL <code>https://&lt;your-host&gt;/scim/v2</code> and the token as the bearer credential. Supported: <code>ServiceProviderConfig</code>, list (<code>startIndex</code>/<code>count</code>, max 200), get by id, the <code>userName eq &quot;…&quot;</code> filter (dedupe — other filters answer 501), create, PUT/PATCH updates, deactivate/delete. While no token exists the endpoints answer 404.</p><p>What provisioning does:</p><ul><li><strong>Create/update</strong> registers the user and links them to their Chat identity (via the Directory, by email).</li><li><strong>Deactivate (or delete)</strong> removes the person from <strong>every standup roster</strong> — offboarding in the IdP actually offboards them here.</li><li>Reactivating does not restore rosters; an admin adds them back with <code>add @user</code> when they return.</li></ul><p>Adding people to specific standups stays an admin action (<code>add @user</code> or the the app) — SCIM has no standup concept, and pushing every provisioned user into every standup would be wrong more often than right.</p>',22)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
